import {defaultCourse,preparedReplies} from './course.js';
import {esc,clone,uid,mmss,hhmm,elapsed,schedule,sectionElapsed,freshSession,validateCourse} from './core.js';
import {read,write,download,fileData} from './storage.js';
import {slideHTML,btn} from './render.js';
import {printContent} from './supports.js';
import {Voice} from './voice.js';
const $=s=>document.querySelector(s), root=$('#app'), modal=$('#modal');
let course=clone(defaultCourse),state=freshSession(),tab='pupitre',history=[],projector,projectorSeen=0,checklist={},saveChain=Promise.resolve();
const params=new URLSearchParams(location.search),view=params.get('view'),channel=new BroadcastChannel('trame-mjc-v1');
const toast=m=>{const t=$('#toast');t.textContent=m;t.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>t.classList.remove('show'),4500)};
try{course=validateCourse(await read('course')||course);state=await read('session')||state;checklist=await read('checklist')||{}}catch(e){toast('Stockage indisponible : exportez votre atelier avant de fermer.');}
state.index=Math.max(0,Math.min(course.slides.length-1,state.index||0));
const current=()=>course.slides[state.index];
const section=()=>course.sections.find(s=>s.id===current().section);
function persist(){const c=clone(course),s=clone(state);saveChain=saveChain.then(()=>Promise.all([write('course',c),write('session',s)])).catch(()=>toast('Sauvegarde locale impossible : exportez votre atelier.'));return saveChain}
function broadcast(){channel.postMessage({type:'state',course,state});}
function checkpoint(){history.push(clone(course));if(history.length>10)history.shift()}
function accrue(){if(state.clock.running&&state.activeSection)state.sectionTime[state.activeSection]=sectionElapsed(state,state.activeSection);state.sectionAnchor=Date.now()}
function go(n){accrue();state.index=Math.max(0,Math.min(course.slides.length-1,n));state.activeSection=current().section;if(current().kind==='pause')voice.stop();state.revealed=false;state.votes=[0,0,0];persist();broadcast();render()}
function command(a){if(a==='next')go(state.index+1);if(a==='prev')go(state.index-1);if(a==='black'||a==='reveal'){state[a==='black'?'black':'revealed']=!state[a==='black'?'black':'revealed'];persist();broadcast();render()}if(a==='stop')voice.stop()}
const voice=new Voice({notify:toast,command,context:()=>`Atelier pour collégiens et lycéens. Slide : ${current().title}. ${current().body.join(' ')}. Notes : ${current().notes||''}`,onText:t=>{if($('#voice-text'))$('#voice-text').textContent=t}});
channel.onmessage=e=>{const d=e.data;if(d.type==='hello'){projectorSeen=Date.now();if(view!=='projector')broadcast()}if(d.type==='state'&&view==='projector'){const changed=JSON.stringify(course)!==JSON.stringify(d.course)||JSON.stringify(state)!==JSON.stringify(d.state);course=d.course;state=d.state;if(changed)renderProjection()}if(d.type==='media'&&view==='projector'){const m=$('[data-media]');if(m){if(m.paused)m.play().catch(()=>toast('Activez le son dans cette fenêtre.'));else m.pause()}}};
function header(){return `<header class="topbar"><div class="brand"><img src="icon.svg" alt=""><div><strong>trame<span>ATELIER IA · MJC YVETOT</span></strong></div></div><nav class="tabs" aria-label="Navigation">${['pupitre','slides','supports','réglages'].map(t=>btn('tab',t[0].toUpperCase()+t.slice(1),'',tab===t?'active':'',`data-tab="${t}"`)).join('')}</nav><div class="top-actions"><span class="status" id="offline-status"><i></i>Vérification hors ligne</span>${btn('export','Sauvegarder','download')}${btn('project','Projeter','screen','primary')}</div></header>`}
function render(){if(view==='projector'){renderProjection();return}if(view==='print'){document.body.className='print-page';root.innerHTML=`<div class="print-toolbar"><strong>Supports de l’atelier</strong>${btn('print','Imprimer / PDF','download')}</div>${printContent(params.get('type'),course)}`;return}root.innerHTML=header()+(tab==='pupitre'?presenter():tab==='slides'?editor():tab==='supports'?supports():settings());tick();offlineStatus()}
function presenter(){const s=current(),sec=section(),times=schedule(course.sections,course.startTime);return `<div class="workspace"><aside class="sidebar"><div class="sidebar-head"><span class="eyebrow">Le fil de l’après-midi</span><small>${course.sections.reduce((n,s)=>n+s.minutes,0)} min</small></div><nav class="section-list" aria-label="Séquences">${course.sections.map((x,i)=>`<button class="section-btn ${x.id===sec.id?'active':''}" data-action="section" data-id="${esc(x.id)}"><span class="number">${i+1}</span><span><strong>${esc(x.title)}</strong><small>${hhmm(times[i].start)} — ${hhmm(times[i].end)}</small></span><span class="duration">${x.minutes}′</span></button>`).join('')}</nav><p class="sidebar-foot">Un pilote, un vérificateur.<br>On essaie. On compare. On décide.</p></aside><main><div class="main-head"><div><span class="eyebrow">${esc(sec.title)}</span><h1>À vous de jouer.</h1></div>${btn('edit-current','Modifier','edit')}</div><div class="preview-shell">${slideHTML(s,course,state.index,state,true)}</div><div class="controls"><div class="nav-control">${btn('prev','Précédente','prev','',state.index===0?'disabled':'')}<span>${state.index+1} / ${course.slides.length}</span>${btn('next','Suivante','next','primary',state.index===course.slides.length-1?'disabled':'')}</div><div class="row">${s.answer?btn('reveal',state.revealed?'Masquer':'Révéler','eye',state.revealed?'on':''):''}${s.media&&s.media.type!=='image'?btn('media','Lecture / pause','volume'):''}${btn('black','Écran noir','black',state.black?'on':'')}</div></div><section class="card notes"><h2>Votre trame</h2><div class="notes-grid"><div><span class="label">À dire / à faire</span><p>${esc(s.notes||sec.notes)}</p></div><div><span class="label">Faire participer</span><p>${esc(s.action)}</p><p class="muted">${esc(s.tip||sec.goal)}</p></div></div>${s.answer?`<div class="votes">${['IA','Sans IA','Indécidable'].map((v,i)=>`<div class="vote">${v}<br>${btn('vote-minus','−','','',`data-vote="${i}"`)}<strong>${state.votes[i]}</strong>${btn('vote-plus','+','','',`data-vote="${i}"`)}</div>`).join('')}</div>`:''}<div class="next-preview"><span class="eyebrow">Ensuite</span><strong>${esc(course.slides[state.index+1]?.title||'Merci et à bientôt !')}</strong></div></section><p class="quick-tip"><span class="kbd">← →</span> changer de slide · <span class="kbd">R</span> révéler · <span class="kbd">B</span> écran noir · <span class="kbd">Échap</span> arrêter la voix</p></main><aside class="right-column"><section class="card"><span class="eyebrow">Temps de la séquence</span><div id="section-clock" class="clock-display"></div><small class="muted">sur ${sec.minutes} minutes prévues</small><div class="progress"><i id="section-progress"></i></div><div class="clock-controls">${btn('clock',state.clock.running?'Mettre en pause':'Démarrer',state.clock.running?'pause':'play','primary')}${btn('reset-clock','Réinitialiser','','','title="Réinitialiser tous les chronomètres"')}</div><div class="clock-meta"><span id="total-clock"></span><span>Fin ${hhmm(times.at(-1).end)}</span></div><p class="pace" id="pace"></p><hr style="border:0;border-top:1px solid var(--line);margin:18px 0"><label>Minuteur de l’activité (minutes)<input id="activity-min" type="number" min="1" max="60" value="5"></label><div class="row">${btn('activity','Lancer','clock')}${btn('activity-stop','Effacer')}</div><p class="help-note" id="activity-status"></p></section><section class="card"><div class="voice-header"><div><h2>Trame</h2><p class="voice-status">${voice.connected?'IA connectée · appui pour parler':'Sans API · micro coupé par défaut'}</p></div><div class="voice-orb"></div></div><div class="voice-buttons">${Object.keys(preparedReplies).map(k=>btn('prepared',({intro:'Présenter Trame',explain:'Expliquer',hint:'Un indice',quiz:'Mini-quiz',debat:'Débattre'})[k],'','',`data-key="${k}"`)).join('')}${btn('stop','Silence','stop')}</div><p class="help-note">Ces interventions sont préparées, lues par la voix de votre appareil. Aucune réponse IA en direct.</p><div class="voice-transcript" id="voice-text">${esc(voice.lastText||'Prêt quand vous l’êtes.')}</div><div class="row">${btn('context','Contexte ChatGPT','link')}${btn('voice-settings','Voix et micro','mic')}</div>${voice.connected?`<label>Question à l’IA<input id="ai-question" placeholder="Une question sur la slide…"></label><div class="row">${btn('ask','Demander')}${btn('talk','Parler / terminer','mic')}</div>`:''}</section></aside></div>`}
function editor(){return `<main class="content-page"><div class="page-header"><div><h1>Un cours qui vous ressemble.</h1><p>Modifiez le contenu, les notes et les médias. Les changements restent sur cet appareil jusqu’à l’export.</p></div><div class="row">${btn('undo','Annuler','','',!history.length?'disabled':'')}${btn('add','Ajouter','plus')}${btn('pdf','Importer un PDF','upload')}</div></div>${course.sections.map(sec=>`<div class="section-title"><h2>${esc(sec.title)}</h2><span class="muted">${sec.minutes} min</span></div><div class="editor-grid">${course.slides.map((s,i)=>s.section===sec.id?`<article class="slide-tile">${slideHTML(s,course,i)}<div class="tile-info"><div><strong>${i+1}. ${esc(s.title)}</strong><small>${esc(s.kind==='media'?'Page PDF / image':'Contenu modifiable')}</small></div><div class="tile-actions">${btn('edit','Modifier','edit','',`data-index="${i}"`)}${btn('duplicate','Copier','','',`data-index="${i}"`)}</div></div></article>`:'').join('')}</div>`).join('')}</main>`}
function supports(){return `<main class="content-page"><div class="page-header"><div><h1>De quoi faire, pas seulement écouter.</h1><p>Les supports sont générés à partir de votre version du cours.</p></div></div><div class="supports-grid">${[['memo','Fiche mémo','Six réflexes à garder après l’atelier.'],['missions','Cartes mission','Cinq défis en binômes, avec des critères de vérification.'],['enquete','Enquête des sources','Un document fictif et son corrigé animateur.'],['trame','Trame animateur','Le déroulé complet, les notes et les réponses.'],['sortie','Billets de sortie','Trois questions pour terminer et retenir.'],['slides','Slides de secours','Une version imprimable de toutes les slides.']].map(([k,t,d],i)=>`<section class="card support-card"><div class="support-icon">0${i+1}</div><h2>${t}</h2><p>${d}</p><div class="row">${btn('support','Ouvrir / imprimer','download','',`data-type="${k}"`)}${['memo','missions'].includes(k)?btn('edit-support','Modifier','edit','',`data-type="${k}"`):''}</div></section>`).join('')}</div></main>`}
function settings(){const times=schedule(course.sections,course.startTime);return `<main class="content-page"><div class="page-header"><div><h1>Prêt pour le jour J.</h1><p>Un atelier autonome, une copie de secours et des commandes simples.</p></div></div><div class="settings-grid"><section class="card"><h2>Votre atelier</h2><form id="course-settings"><label>Titre<input name="title" value="${esc(course.title)}" required></label><label>Lieu<input name="venue" value="${esc(course.venue)}" required></label><div class="two-col"><label>Date<input name="date" type="date" value="${esc(course.date)}" required></label><label>Début<input name="startTime" type="time" value="${esc(course.startTime)}" required></label></div><button class="primary">Enregistrer</button></form><div class="callout">Sur une autre machine : ouvrez ce site puis importez votre sauvegarde. GitHub distribue le cours initial ; vos retouches ne sont pas synchronisées automatiquement.</div><div class="row">${btn('export','Exporter tout','download')}${btn('import','Importer','upload')}</div></section><section class="card check-list"><h2>La répétition générale</h2>${course.checklist.map((t,i)=>`<label><input type="checkbox" data-check="${i}" ${checklist[i]?'checked':''}>${esc(t)}</label>`).join('')}<p class="help-note">La voix et le vidéoprojecteur doivent être essayés avec le matériel qui sera réellement utilisé.</p></section><section class="card"><h2>Le tempo · ${course.sections.reduce((a,s)=>a+s.minutes,0)} minutes</h2><table class="schedule-table"><thead><tr><th>Séquence</th><th>Horaire</th><th>Minutes</th></tr></thead><tbody>${course.sections.map((s,i)=>`<tr><td>${esc(s.title)}</td><td>${hhmm(times[i].start)}</td><td><input aria-label="Durée ${esc(s.title)}" type="number" min="1" max="180" data-duration="${esc(s.id)}" value="${s.minutes}"></td></tr>`).join('')}</tbody></table><p class="help-note">Le passage des slides reste volontaire. Le compteur signale un dépassement sans interrompre une activité.</p></section><section class="card"><h2>Voix, confidentialité et secours</h2><p>Le cours et les jeux fonctionnent sans compte IA. La voix de l’appareil lit les interventions préparées ; sa qualité dépend du système.</p>${btn('voice-settings','Configurer la voix','mic')}<div class="callout">Aucun enregistrement continu par défaut. Le micro facultatif peut utiliser un service distant du navigateur. Pas de reconnaissance biométrique du présentateur.</div><p>Pour une voix IA naturelle : branchement OpenAI Realtime préparé dans le serveur fourni. Facturation API séparée de ChatGPT. Aucun secret dans GitHub Pages.</p><p class="help-note">Raccourcis clavier et télécommande USB restent les commandes de référence. Gardez les supports PDF et la sauvegarde sur une clé USB.</p>${btn('reset-course','Revenir au cours initial','','danger')}</section></div></main>`}
function renderProjection(){document.body.className='projector-page';root.innerHTML=`<main class="projection-shell">${slideHTML(current(),course,state.index,state,true)}</main><div class="projection-toolbar">${btn('fullscreen','Plein écran','screen')}${btn('media','Lecture / pause','volume')}</div>${!window.projectionStarted?`<div class="projection-intro"><div class="inner"><p class="eyebrow">TRAME · ÉCRAN PUBLIC</p><h1>Place aux jeunes.</h1><p>Déplacez cette fenêtre sur le vidéoprojecteur. Les notes restent dans le pupitre.</p>${btn('projection-start','Afficher les slides','play','accent')}</div></div>`:''}`;tick()}
function tick(){const now=Date.now();document.querySelectorAll('[data-activity]').forEach(x=>x.textContent=mmss(Math.max(0,state.activityEnd-now)));if(!$('#section-clock'))return;const used=sectionElapsed(state,section().id),budget=section().minutes*60000;$('#section-clock').textContent=mmss(budget-used);$('#section-clock').classList.toggle('late',used>budget);$('#section-progress').style.width=Math.min(100,used/budget*100)+'%';$('#total-clock').textContent=mmss(elapsed(state.clock))+' écoulées';const idx=course.sections.indexOf(section()),prior=course.sections.slice(0,idx).reduce((n,s)=>n+s.minutes*60000,0),delta=elapsed(state.clock)-prior-used;$('#pace').textContent=!state.clock.startedAt?'Lancez le chrono au début de l’atelier.':(used>budget?'Séquence dépassée : concluez ou raccourcissez la suivante.':delta>60000?`${Math.round(delta/60000)} min de retard sur le déroulé.`:delta< -60000?`${Math.round(-delta/60000)} min d’avance sur le déroulé.`:'Vous êtes dans le tempo.');$('#activity-status').textContent=state.activityEnd?(now>=state.activityEnd?'Temps de l’activité écoulé.':`Activité : ${mmss(state.activityEnd-now)}`):'Visible aussi sur le vidéoprojecteur.';}
function dialog(title,body,footer=''){modal.innerHTML=`<div class="modal-head"><h2>${title}</h2>${btn('close','Fermer','close')}</div><div class="modal-body">${body}</div>${footer?`<div class="modal-foot">${footer}</div>`:''}`;modal.showModal()}
function editSlide(i){const s=course.slides[i];dialog('Modifier la slide',`<form id="slide-form" data-index="${i}"><label>Titre<input name="title" maxlength="180" value="${esc(s.title)}" required></label><label>Sous-titre<input name="subtitle" value="${esc(s.subtitle)}"></label><div class="two-col"><label>Séquence<select name="section">${course.sections.map(x=>`<option value="${esc(x.id)}" ${s.section===x.id?'selected':''}>${esc(x.title)}</option>`).join('')}</select></label><label>Disposition<select name="kind">${['cover','cards','statement','exercise','game','pause','media','closing'].map(k=>`<option ${s.kind===k?'selected':''}>${k}</option>`).join('')}</select></label></div><label>Contenu (une ligne par idée ; carte : titre | description)<textarea name="body" rows="5">${esc(s.body.join('\n'))}</textarea></label><label>Notes animateur<textarea name="notes">${esc(s.notes)}</textarea></label><label>Action participative<textarea name="action">${esc(s.action)}</textarea></label><label>Réponse à révéler<input name="answer" value="${esc(s.answer||'')}"></label><label>Explication<textarea name="explanation">${esc(s.explanation||'')}</textarea></label><label>Source / provenance<input name="source" value="${esc(s.source||'')}"></label><label>Thème<select name="theme"><option value="light" ${s.theme==='light'?'selected':''}>Clair</option><option value="dark" ${s.theme==='dark'?'selected':''}>Nuit</option></select></label><label>Média (image, audio, vidéo · 30 Mo maximum)<input name="mediaFile" type="file" accept="image/png,image/jpeg,image/webp,image/gif,audio/mpeg,audio/wav,audio/ogg,video/mp4,video/webm"></label>${s.media?'<label><input type="checkbox" name="removeMedia">Retirer le média actuel</label>':''}<label>Position dans le cours<input name="position" type="number" min="1" max="${course.slides.length}" value="${i+1}"></label><div class="row"><button class="primary">Enregistrer</button>${btn('delete','Supprimer','','danger',`data-index="${i}"`)}</div></form>`)}
async function exportAll(){toast('Préparation de la sauvegarde avec les médias…');const c=clone(course);for(const s of c.slides)if(s.media?.src.startsWith('assets/'))s.media.src=await fileData(await(await fetch(s.media.src)).blob());download('atelier-mjc-'+new Date().toISOString().slice(0,10)+'.trame',JSON.stringify({format:'trame-backup',version:1,course:c,state,checklist}));toast('Sauvegarde téléchargée. Gardez-la sur votre clé USB.');}
function chooseFile(accept,callback){const f=document.createElement('input');f.type='file';f.accept=accept;f.onchange=()=>{if(f.files[0])callback(f.files[0]).catch(e=>toast(e.message))};f.click()}
async function importBackup(file){if(file.size>150*1024*1024)throw Error('Sauvegarde limitée à 150 Mo.');const b=JSON.parse(await file.text());validateCourse(b.course);if(!confirm('Remplacer cet atelier par la sauvegarde ? Exportez auparavant vos modifications si nécessaire.'))return;checkpoint();course=b.course;state=freshSession();if(b.state){state.index=Math.max(0,Math.min(course.slides.length-1,Number(b.state.index)||0));state.clock.elapsed=Math.max(0,Math.min(86400000,elapsed(b.state.clock||{})));state.clock.startedAt=Number(b.state.clock?.startedAt)||0;state.sectionTime=b.state.sectionTime&&typeof b.state.sectionTime==='object'?b.state.sectionTime:{}}checklist=b.checklist||{};await persist();broadcast();render();toast('Atelier importé. Chronomètres en pause.');}
async function importPDF(file){if(file.size>50*1024*1024)throw Error('PDF limité à 50 Mo.');toast('Lecture du PDF…');const pdfjs=await import('./vendor/pdf.min.mjs');pdfjs.GlobalWorkerOptions.workerSrc=new URL('./vendor/pdf.worker.min.mjs',import.meta.url).href;const doc=await pdfjs.getDocument({data:new Uint8Array(await file.arrayBuffer()),isEvalSupported:false}).promise;dialog('Importer depuis Keynote',`<p>${doc.numPages} page(s). Exportez vos slides Keynote en PDF ; le rendu visuel est conservé. Les notes restent modifiables dans Trame.</p><form id="pdf-form"><label>Pages (ex. 1,3-5)<input name="pages" value="1-${doc.numPages}" required></label><label>Insertion<select name="mode"><option value="append">Ajouter après la slide actuelle</option><option value="replace">Remplacer la slide actuelle (une page)</option></select></label><button class="primary">Importer les pages</button></form>`);$('#pdf-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),pages=[];try{for(const part of f.get('pages').split(',')){const m=part.trim().match(/^(\d+)(?:-(\d+))?$/);if(!m)throw Error('Liste de pages invalide.');const a=+m[1],b=+(m[2]||m[1]);if(a<1||b>doc.numPages||b<a||b-a>100)throw Error('Pages hors limites.');for(let n=a;n<=b;n++)pages.push(n)}if(pages.length>80||course.slides.length+pages.length>200)throw Error('Trop de pages (200 slides maximum).');if(f.get('mode')==='replace'&&pages.length!==1)throw Error('Sélectionnez une seule page pour remplacer.');e.target.querySelector('button').disabled=true;checkpoint();const slides=[];for(const n of pages){const page=await doc.getPage(n),vp=page.getViewport({scale:1}),v=page.getViewport({scale:1600/vp.width}),canvas=document.createElement('canvas');canvas.width=v.width;canvas.height=v.height;await page.render({canvasContext:canvas.getContext('2d'),viewport:v}).promise;slides.push({...clone(current()),id:uid(),kind:'media',title:`${file.name} · ${n}`,media:{type:'image',src:canvas.toDataURL('image/jpeg',.88),alt:`Page ${n} du PDF importé`},answer:'',body:[]})}if(f.get('mode')==='replace'){slides[0].notes=current().notes;course.slides.splice(state.index,1,...slides)}else course.slides.splice(state.index+1,0,...slides);await persist();modal.close();broadcast();render();toast('PDF importé. Vérifiez le cadrage dans le pupitre.')}catch(err){toast(err.message);e.target.querySelector('button').disabled=false}}}
function voiceSettings(){dialog('Trame · voix et micro',`<label>Voix de cet appareil<select id="voice-choice"><option value="">Français automatique</option>${speechSynthesis.getVoices().filter(v=>v.lang.startsWith('fr')).map(v=>`<option value="${esc(v.name)}" ${voice.voiceName===v.name?'selected':''}>${esc(v.name)}</option>`).join('')}</select></label><div class="row">${btn('voice-test','Écouter un essai','volume')}${btn('recognition',voice.listening?'Couper le micro':'Activer les commandes vocales','mic')}</div><p class="help-note">Facultatif, surtout Chrome / Edge. Le navigateur peut envoyer l’audio à son prestataire. Activez seulement avec l’accord du groupe ; rien n’est sauvegardé par cette application. « Trame, suivante », « suivante, Trame » ou « slide Trame suivante ». Toute voix peut déclencher une commande. Le micro se coupe après 10 minutes et pendant les interventions parlées.</p><hr><h3>IA en direct · branchement optionnel</h3><p class="help-note">Nécessite le serveur fourni et une clé API OpenAI côté serveur. Votre abonnement ChatGPT ne finance pas cette connexion. Aucune clé API ne doit être saisie ici.</p><label>Adresse du serveur sécurisé<input id="api-url" type="url" placeholder="https://votre-serveur.example" value="${esc(voice.endpoint||'')}"></label><label>Code d’accès du serveur (si hébergé)<input id="api-access" type="password" autocomplete="off"></label><div class="row">${btn('connect-ai','Connecter l’IA')}${btn('disconnect-ai','Déconnecter')}</div><p class="help-note">Session limitée à 10 minutes ; appui pour parler, 20 secondes maximum par prise. Aucune écoute de toute la salle. La qualité et la latence restent dépendantes du réseau et du matériel.</p>`)}
root.addEventListener('submit',async e=>{e.preventDefault();if(e.target.id==='course-settings'){checkpoint();Object.assign(course,Object.fromEntries(new FormData(e.target)));await persist();broadcast();render();toast('Atelier enregistré.')}});
modal.addEventListener('submit',async e=>{if(e.target.id!=='slide-form')return;e.preventDefault();try{const f=new FormData(e.target),i=+e.target.dataset.index,s=clone(course.slides[i]);for(const k of ['title','subtitle','section','kind','notes','action','answer','explanation','source','theme'])s[k]=f.get(k);s.body=f.get('body').split('\n').filter(Boolean);if(f.get('removeMedia'))delete s.media;const file=f.get('mediaFile');if(file?.size){if(file.size>30*1024*1024)throw Error('Média limité à 30 Mo.');s.media={type:file.type.split('/')[0],src:await fileData(file),alt:s.title}}const c=clone(course);c.slides.splice(i,1);c.slides.splice(Math.max(0,Math.min(c.slides.length,+f.get('position')-1)),0,s);validateCourse(c);checkpoint();course=c;state.index=course.slides.findIndex(x=>x.id===s.id);await persist();modal.close();broadcast();render();toast('Slide enregistrée.')}catch(err){toast(err.message)}});
document.addEventListener('change',async e=>{if(e.target.matches('[data-duration]')){const n=Number(e.target.value);if(!Number.isInteger(n)||n<1||n>180){toast('Durée de 1 à 180 minutes.');render();return}checkpoint();course.sections.find(s=>s.id===e.target.dataset.duration).minutes=n;await persist();render()}if(e.target.matches('[data-check]')){checklist[e.target.dataset.check]=e.target.checked;write('checklist',checklist)}if(e.target.id==='voice-choice')voice.voiceName=e.target.value});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;try{
if(['next','prev','black','reveal','stop'].includes(a)){command(a);return}
if(a==='tab'){tab=b.dataset.tab;render()}if(a==='section')go(course.slides.findIndex(s=>s.section===b.dataset.id));
if(a==='project'){projector=window.open(new URL('?view=projector',location.href),'trame-projector','popup,width=1280,height=720');if(!projector)toast('Autorisez les fenêtres surgissantes pour afficher le projecteur.');else toast('Déplacez la fenêtre sur le vidéoprojecteur, puis affichez les slides.')}
if(a==='projection-start'){window.projectionStarted=true;renderProjection();document.documentElement.requestFullscreen?.().catch(()=>{})}if(a==='fullscreen')document.documentElement.requestFullscreen?.();
if(a==='media'){if(view==='projector'||Date.now()-projectorSeen>5000){const m=$('[data-media]');if(m){if(m.paused)await m.play();else m.pause()}}else channel.postMessage({type:'media'})}
if(a==='clock'){accrue();if(state.clock.running){state.clock.elapsed=elapsed(state.clock);state.clock.running=false;voice.stopListening()}else{state.clock.running=true;state.clock.anchor=Date.now();state.clock.startedAt||=Date.now();state.activeSection=current().section;state.sectionAnchor=Date.now()}await persist();broadcast();render()}
if(a==='reset-clock'&&confirm('Remettre tous les chronomètres à zéro ?')){state={...freshSession(),index:state.index};await persist();broadcast();render()}
if(a==='activity'){state.activityEnd=Date.now()+Math.max(1,Math.min(60,+$('#activity-min').value||5))*60000;broadcast();render()}if(a==='activity-stop'){state.activityEnd=0;broadcast();render()}
if(a.startsWith('vote-')){const i=+b.dataset.vote;state.votes[i]=Math.max(0,state.votes[i]+(a==='vote-plus'?1:-1));render()}
if(a==='edit-current')editSlide(state.index);if(a==='edit')editSlide(+b.dataset.index);if(a==='close')modal.close();if(a==='print')window.print();
if(a==='duplicate'){checkpoint();const i=+b.dataset.index;course.slides.splice(i+1,0,{...clone(course.slides[i]),id:uid(),title:course.slides[i].title+' · copie'});await persist();render()}
if(a==='add'){checkpoint();course.slides.push({id:uid(),section:section().id,kind:'statement',title:'Votre nouvelle idée',subtitle:'',body:['Une idée, une question, une action.'],notes:'',action:'',theme:'light'});await persist();editSlide(course.slides.length-1)}
if(a==='delete'&&course.slides.length>1&&confirm('Supprimer cette slide ?')){checkpoint();course.slides.splice(+b.dataset.index,1);state.index=Math.min(state.index,course.slides.length-1);await persist();modal.close();render();broadcast()}
if(a==='undo'&&history.length){course=history.pop();state.index=Math.min(state.index,course.slides.length-1);await persist();render();broadcast()}
if(a==='export')await exportAll();if(a==='import')chooseFile('.trame,.json',importBackup);if(a==='pdf')chooseFile('.pdf',importPDF);
if(a==='support')window.open(`?view=print&type=${b.dataset.type}`,'_blank');
if(a==='edit-support'){const type=b.dataset.type;dialog('Modifier le support',`<p>Chaque carte reste liée à votre atelier. Les champs sont séparés pour préserver la mise en page.</p><form id="support-form">${course[type].map((m,i)=>`<fieldset><legend>${i+1}. ${esc(m.title)}</legend>${Object.entries(m).map(([k,v])=>`<label>${esc(({title:'Titre',text:'Texte',task:'Mission',prompt:'Demande de départ',check:'Vérifications',human:'Contribution humaine',advanced:'Pour aller plus loin'})[k]||k)}<textarea name="${i}:${k}">${esc(v)}</textarea></label>`).join('')}</fieldset>`).join('')}<button class="primary">Enregistrer</button></form>`);$('#support-form').onsubmit=async ev=>{ev.preventDefault();checkpoint();for(const [k,v]of new FormData(ev.target)){const [i,key]=k.split(':');course[type][i][key]=v}await persist();modal.close();toast('Support enregistré.')}}
if(a==='prepared')voice.speak(preparedReplies[b.dataset.key]);if(a==='voice-settings')voiceSettings();if(a==='voice-test')voice.speak('Bonjour, je suis Trame. Aujourd’hui, c’est vous qui gardez la main.');if(a==='recognition'){if(voice.listening)voice.stopListening();else voice.startListening();modal.close()}
if(a==='context'){dialog('Contexte à copier dans ChatGPT',`<p>Ouvrez ChatGPT sur votre compte et collez ce contexte. Ne transmettez pas de noms ni de propos personnels de jeunes.</p><textarea id="context-copy" rows="9">${esc(voice.context()+'\nRéponds en français, en 45 secondes maximum, pour des adolescents. Signale tes incertitudes. Ne prétends pas connaître les participants.\nQuestion : ')}</textarea><div class="row">${btn('copy-context','Copier')}<a href="https://chatgpt.com/" target="_blank" rel="noopener">Ouvrir ChatGPT</a></div>`)}if(a==='copy-context'){await navigator.clipboard.writeText($('#context-copy').value);toast('Contexte copié.')}
if(a==='connect-ai'){await voice.connect($('#api-url').value,$('#api-access').value);modal.close();render()}if(a==='disconnect-ai'){voice.disconnect();modal.close();render()}if(a==='ask'){voice.ask($('#ai-question').value);$('#ai-question').value=''}if(a==='talk')voice.toggleTalk();
if(a==='reset-course'&&confirm('Revenir au cours initial ? Exportez vos modifications avant de continuer.')){checkpoint();course=clone(defaultCourse);state=freshSession();await persist();render();broadcast()}
}catch(err){console.error(err);toast(err.message||'Cette action a échoué.')}});
document.addEventListener('keydown',e=>{if(/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||modal.open||view==='print')return;const a=({ArrowRight:'next',PageDown:'next',' ':'next',ArrowLeft:'prev',PageUp:'prev',r:'reveal',b:'black',Escape:'stop'})[e.key];if(a&&view!=='projector'){e.preventDefault();command(a)}});
let offlineReady=false;function offlineStatus(){const e=$('#offline-status');if(e){e.classList.toggle('good',offlineReady);e.innerHTML=`<i></i>${offlineReady?'Prêt hors ligne':'En ligne · cache en préparation'}`}}
if('serviceWorker'in navigator){navigator.serviceWorker.register('./sw.js').then(async()=>{await navigator.serviceWorker.ready;const keys=await caches.keys();offlineReady=keys.some(k=>k.startsWith('trame-static'));offlineStatus()}).catch(()=>toast('Mode hors ligne indisponible ici. Gardez la copie locale.'))}
render();setInterval(tick,250);if(view==='projector'){channel.postMessage({type:'hello'});setInterval(()=>channel.postMessage({type:'hello'}),2000)}else{setInterval(()=>{if(state.clock.running)persist()},10000);window.addEventListener('beforeunload',()=>voice.disconnect());}
